#### Phase 2: Implement Transactional Outbox Pattern (2-3 weeks)

**Goal**: Ensure events published if and only if database transaction commits. Prevents inconsistencies where database commits but event publishing fails (or vice versa).

**Problem**: In Phase 1 implementation, database commit and event publishing are separate operations:

```csharp
await _repository.InsertAsync(member); // Step 1: Database commit
await _eventPublisher.SendMessageAsync(message); // Step 2: Publish event
```

If database commits but service crashes before publishing event, system inconsistent: member enrolled in Member Service but Claims Service never notified.

**Solution**: Transactional Outbox Pattern: Store events in database as part of same transaction; background process reads events from database and publishes to message bus.

**Steps**:

**Step 2.1: Create Outbox Table**

```sql
CREATE TABLE OutboxEvents (
    EventId UNIQUEIDENTIFIER PRIMARY KEY,
    AggregateId UNIQUEIDENTIFIER NOT NULL,      -- Member ID, Claim ID, etc.
    AggregateType VARCHAR(100) NOT NULL,        -- "Member", "Claim", etc.
    EventType VARCHAR(100) NOT NULL,            -- "member.enrolled"
    EventPayload NVARCHAR(MAX) NOT NULL,        -- JSON event data
    CorrelationId VARCHAR(100),                  -- For distributed tracing
    CreatedAt DATETIME2 NOT NULL DEFAULT GETUTCDATE(),
    ProcessedAt DATETIME2 NULL,                 -- When published to message bus
    Status VARCHAR(50) NOT NULL DEFAULT 'Pending', -- Pending, Published, Failed
    RetryCount INT NOT NULL DEFAULT 0,
    LastError NVARCHAR(MAX) NULL,
    INDEX IX_Status_CreatedAt (Status, CreatedAt)
);
```

**Step 2.2: Modify Service to Write to Outbox**

```csharp
public class MemberService {
    private readonly IMemberRepository _repository;
    private readonly IDbTransaction _transaction;

    public async Task EnrollMemberAsync(MemberEnrollmentRequest request) {
        // Begin database transaction
        using var transaction = await _transaction.BeginAsync();

        try {
            // Step 1: Insert member (same transaction)
            var member = new Member {
                Id = Guid.NewGuid(),
                FirstName = request.FirstName,
                LastName = request.LastName,
                EnrollmentDate = DateTime.UtcNow
            };
            await _repository.InsertAsync(member);

            // Step 2: Insert event into outbox (same transaction)
            var outboxEvent = new OutboxEvent {
                EventId = Guid.NewGuid(),
                AggregateId = member.Id,
                AggregateType = "Member",
                EventType = "member.enrolled",
                EventPayload = JsonSerializer.Serialize(new {
                    MemberId = member.Id,
                    FirstName = member.FirstName,
                    LastName = member.LastName,
                    EnrollmentDate = member.EnrollmentDate
                }),
                CorrelationId = Activity.Current?.Id ?? Guid.NewGuid().ToString(),
                Status = "Pending"
            };
            await _repository.InsertOutboxEventAsync(outboxEvent);

            // Commit transaction (atomically commits both member and outbox event)
            await transaction.CommitAsync();

            _logger.LogInformation(
                "Member enrolled and event written to outbox: {MemberId}, EventId: {EventId}",
                member.Id, outboxEvent.EventId
            );

        } catch (Exception ex) {
            await transaction.RollbackAsync();
            _logger.LogError(ex, "Failed to enroll member");
            throw;
        }
    }
}
```

**Step 2.3: Implement Outbox Publisher (Background Service)**

```csharp
// Background service that reads outbox and publishes to message bus
public class OutboxPublisher : BackgroundService {
    private readonly IServiceProvider _serviceProvider;
    private readonly IServiceBusSender _eventPublisher;
    private readonly ILogger<OutboxPublisher> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        while (!stoppingToken.IsCancellationRequested) {
            try {
                await ProcessOutboxEventsAsync();
                await Task.Delay(TimeSpan.FromSeconds(5), stoppingToken);
            } catch (Exception ex) {
                _logger.LogError(ex, "Error in outbox publisher");
                await Task.Delay(TimeSpan.FromSeconds(30), stoppingToken);
            }
        }
    }

    private async Task ProcessOutboxEventsAsync() {
        using var scope = _serviceProvider.CreateScope();
        var repository = scope.ServiceProvider.GetRequiredService<IOutboxRepository>();

        // Fetch pending events (ordered by creation time)
        var pendingEvents = await repository.GetPendingEventsAsync(batchSize: 100);

        foreach (var outboxEvent in pendingEvents) {
            try {
                // Publish to message bus
                var message = new ServiceBusMessage(outboxEvent.EventPayload) {
                    MessageId = outboxEvent.EventId.ToString(),
                    CorrelationId = outboxEvent.CorrelationId,
                    ContentType = "application/json",
                    Subject = outboxEvent.EventType
                };

                await _eventPublisher.SendMessageAsync(message);

                // Mark as published
                await repository.MarkAsPublishedAsync(outboxEvent.EventId);

                _logger.LogInformation(
                    "Published outbox event: {EventId}, Type: {EventType}",
                    outboxEvent.EventId, outboxEvent.EventType
                );

            } catch (Exception ex) {
                // Increment retry count, record error
                await repository.IncrementRetryCountAsync(outboxEvent.EventId, ex.Message);

                _logger.LogError(ex,
                    "Failed to publish outbox event: {EventId}, Retry: {RetryCount}",
                    outboxEvent.EventId, outboxEvent.RetryCount + 1
                );

                // Move to failed status after 5 retries
                if (outboxEvent.RetryCount >= 5) {
                    await repository.MarkAsFailedAsync(outboxEvent.EventId);

                    await _alertService.NotifyAsync(new Alert {
                        Severity = "high",
                        Message = $"Outbox event failed after retries: {outboxEvent.EventId}",
                        Details = new { EventType = outboxEvent.EventType, Error = ex.Message }
                    });
                }
            }
        }
    }
}
```

**Step 2.4: Implement Outbox Cleanup Job**

```csharp
// Cleanup old published events to prevent unbounded growth
public class OutboxCleanupJob : BackgroundService {
    private readonly IServiceProvider _serviceProvider;
    private readonly ILogger<OutboxCleanupJob> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        while (!stoppingToken.IsCancellationRequested) {
            try {
                await CleanupOldEventsAsync();
                await Task.Delay(TimeSpan.FromHours(24), stoppingToken); // Run daily
            } catch (Exception ex) {
                _logger.LogError(ex, "Error in outbox cleanup job");
            }
        }
    }

    private async Task CleanupOldEventsAsync() {
        using var scope = _serviceProvider.CreateScope();
        var repository = scope.ServiceProvider.GetRequiredService<IOutboxRepository>();

        // Delete published events older than 7 days
        var cutoffDate = DateTime.UtcNow.AddDays(-7);
        var deletedCount = await repository.DeletePublishedEventsAsync(cutoffDate);

        _logger.LogInformation(
            "Outbox cleanup: Deleted {Count} events older than {Date}",
            deletedCount, cutoffDate
        );
    }
}
```

**Validation Criteria**:
- Member enrollment and event written to outbox atomically (check database: member row and outbox row both present or both absent)
- Outbox publisher processes events (check logs: "Published outbox event")
- Outbox events marked as published (query: `SELECT COUNT(*) FROM OutboxEvents WHERE Status='Published'`)
- Failed events moved to failed status after retries (query: `SELECT * FROM OutboxEvents WHERE Status='Failed'`)
- Cleanup job deletes old events (check outbox table size doesn't grow unbounded)

