#### Phase 4: Implement Saga Pattern (3-4 weeks)

**Goal**: Coordinate distributed transactions with compensation logic.

**Steps**:

**Step 4.1: Design Saga Workflow**

```yaml
# Member Enrollment Saga
saga: member-enrollment
steps:

  - name: enroll-member
    service: member-service
    command: EnrollMember
    compensation: RollbackEnrollment

  - name: create-eligibility
    service: eligibility-service
    command: CreateEligibility
    compensation: DeleteEligibility

  - name: enable-claims
    service: claims-service
    command: EnableClaimsProcessing
    compensation: DisableClaimsProcessing

  - name: create-payment-account
    service: payment-service
    command: CreatePaymentAccount
    compensation: DeletePaymentAccount

  - name: notify-member
    service: notification-service
    command: SendWelcomeEmail
    compensation: null # No compensation for notification
```

**Step 4.2: Implement Orchestrator (Orchestration-Based Saga)**

```csharp
public class MemberEnrollmentSaga {
    private readonly IMemberService _memberService;
    private readonly IEligibilityService _eligibilityService;
    private readonly IClaimsService _claimsService;
    private readonly IPaymentService _paymentService;
    private readonly INotificationService _notificationService;
    private readonly ISagaRepository _sagaRepository;

    public async Task<SagaResult> ExecuteAsync(MemberEnrollmentRequest request) {
        // Create saga instance
        var sagaId = Guid.NewGuid();
        var saga = new SagaInstance {
            SagaId = sagaId,
            SagaType = "member-enrollment",
            Status = "Running",
            StartedAt = DateTime.UtcNow,
            CorrelationId = Activity.Current?.Id ?? Guid.NewGuid().ToString()
        };
        await _sagaRepository.CreateAsync(saga);

        var completedSteps = new List<string>();

        try {
            // Step 1: Enroll member
            await RecordStepAsync(sagaId, "enroll-member", "Started");
            var memberId = await _memberService.EnrollMemberAsync(request);
            await RecordStepAsync(sagaId, "enroll-member", "Completed", new { memberId });
            completedSteps.Add("enroll-member");

            // Step 2: Create eligibility
            await RecordStepAsync(sagaId, "create-eligibility", "Started");
            await _eligibilityService.CreateEligibilityAsync(memberId);
            await RecordStepAsync(sagaId, "create-eligibility", "Completed");
            completedSteps.Add("create-eligibility");

            // Step 3: Enable claims processing
            await RecordStepAsync(sagaId, "enable-claims", "Started");
            await _claimsService.EnableClaimsProcessingAsync(memberId);
            await RecordStepAsync(sagaId, "enable-claims", "Completed");
            completedSteps.Add("enable-claims");

            // Step 4: Create payment account
            await RecordStepAsync(sagaId, "create-payment-account", "Started");
            await _paymentService.CreatePaymentAccountAsync(memberId);
            await RecordStepAsync(sagaId, "create-payment-account", "Completed");
            completedSteps.Add("create-payment-account");

            // Step 5: Send welcome email
            await RecordStepAsync(sagaId, "notify-member", "Started");
            await _notificationService.SendWelcomeEmailAsync(memberId, request.Email);
            await RecordStepAsync(sagaId, "notify-member", "Completed");

            // Saga completed successfully
            await _sagaRepository.MarkAsCompletedAsync(sagaId);

            return new SagaResult {
                SagaId = sagaId,
                Status = "Completed",
                MemberId = memberId
            };

        } catch (Exception ex) {
            _logger.LogError(ex, "Saga failed: {SagaId}, Step: {Step}", sagaId, completedSteps.LastOrDefault());

            // Compensate completed steps in reverse order
            await CompensateAsync(sagaId, completedSteps, request);

            return new SagaResult {
                SagaId = sagaId,
                Status = "Failed",
                Error = ex.Message
            };
        }
    }

    private async Task CompensateAsync(Guid sagaId, List<string> completedSteps, MemberEnrollmentRequest request) {
        await _sagaRepository.MarkAsCompensatingAsync(sagaId);

        // Reverse order: compensate in LIFO order
        completedSteps.Reverse();

        foreach (var step in completedSteps) {
            try {
                await RecordStepAsync(sagaId, step, "Compensating");

                switch (step) {
                    case "enroll-member":
                        await _memberService.RollbackEnrollmentAsync(request.SSN);
                        break;
                    case "create-eligibility":
                        await _eligibilityService.DeleteEligibilityAsync(request.SSN);
                        break;
                    case "enable-claims":
                        await _claimsService.DisableClaimsProcessingAsync(request.SSN);
                        break;
                    case "create-payment-account":
                        await _paymentService.DeletePaymentAccountAsync(request.SSN);
                        break;
                }

                await RecordStepAsync(sagaId, step, "Compensated");

            } catch (Exception ex) {
                _logger.LogError(ex, "Compensation failed: {SagaId}, Step: {Step}", sagaId, step);

                // Alert operations team for manual intervention
                await _alertService.NotifyAsync(new Alert {
                    Severity = "critical",
                    Message = $"Saga compensation failed: {sagaId}",
                    Details = new { SagaId = sagaId, Step = step, Error = ex.Message }
                });

                await RecordStepAsync(sagaId, step, "Compensation Failed", new { error = ex.Message });
            }
        }

        await _sagaRepository.MarkAsCompensatedAsync(sagaId);
    }

    private async Task RecordStepAsync(Guid sagaId, string stepName, string status, object data = null) {
        await _sagaRepository.RecordStepAsync(new SagaStep {
            SagaId = sagaId,
            StepName = stepName,
            Status = status,
            Timestamp = DateTime.UtcNow,
            Data = data != null ? JsonSerializer.Serialize(data) : null
        });
    }
}
```

**Step 4.3: Implement Compensating Transactions**

```csharp
// Member Service: Compensation logic
public class MemberService {
    public async Task RollbackEnrollmentAsync(string ssn) {
        // Find member by SSN (business key)
        var member = await _repository.FindBySSNAsync(ssn);
        if (member == null) {
            _logger.LogWarning("Compensation: Member not found for SSN: {SSN}", ssn);
            return; // Already compensated or never created
        }

        // Mark enrollment as rolled back (soft delete)
        member.Status = "Enrollment Rolled Back";
        member.RolledBackAt = DateTime.UtcNow;
        await _repository.UpdateAsync(member);

        // Publish compensation event
        await _eventPublisher.PublishAsync(new MemberEnrollmentRolledBackEvent {
            EventType = "member.enrollment.rolled.back",
            Data = new { MemberId = member.Id, SSN = ssn, Reason = "Saga compensation" }
        });

        _logger.LogInformation("Compensated member enrollment: {MemberId}, SSN: {SSN}", member.Id, ssn);
    }
}
```

**Step 4.4: Implement Saga State Persistence**

```sql
-- Saga instance table
CREATE TABLE SagaInstances (
    SagaId UNIQUEIDENTIFIER PRIMARY KEY,
    SagaType VARCHAR(100) NOT NULL,        -- "member-enrollment"
    Status VARCHAR(50) NOT NULL,           -- Running, Completed, Failed, Compensating, Compensated
    CorrelationId VARCHAR(100),
    StartedAt DATETIME2 NOT NULL,
    CompletedAt DATETIME2 NULL,
    Data NVARCHAR(MAX),                    -- Request payload
    INDEX IX_Status (Status),
    INDEX IX_CorrelationId (CorrelationId)
);

-- Saga step table
CREATE TABLE SagaSteps (
    StepId UNIQUEIDENTIFIER PRIMARY KEY,
    SagaId UNIQUEIDENTIFIER NOT NULL FOREIGN KEY REFERENCES SagaInstances(SagaId),
    StepName VARCHAR(100) NOT NULL,        -- "enroll-member", "create-eligibility"
    Status VARCHAR(50) NOT NULL,           -- Started, Completed, Failed, Compensating, Compensated
    Timestamp DATETIME2 NOT NULL,
    Data NVARCHAR(MAX),                    -- Step result or error
    INDEX IX_SagaId (SagaId, Timestamp)
);
```

**Validation Criteria**:
- Successful saga: all steps complete, saga status = "Completed"
- Failed saga: compensation executes in reverse order, saga status = "Compensated"
- Saga state persisted (query SagaInstances table; see saga history)
- Compensation failures alert operations team (check alerting system)

