#### Phase 5: Implement Reconciliation (2-3 weeks)

**Goal**: Detect and resolve inconsistencies between services.

**Steps**:

**Step 5.1: Implement Scheduled Reconciliation Job**

```javascript
// Reconciliation job (runs nightly at 2 AM)
const schedule = require('node-schedule');

schedule.scheduleJob('0 2 * * *', async () => {
    console.log('Starting member eligibility reconciliation...');

    const startTime = Date.now();

    // Query source of truth (Member Service)
    const activeMembers = await memberServiceClient.getActiveMembers();
    console.log(`Source of truth: ${activeMembers.length} active members`);

    // Query replica (Claims Service cache)
    const cachedMembers = await claimsServiceClient.getEligibilityCache();
    console.log(`Cached data: ${cachedMembers.length} members`);

    const discrepancies = [];

    // Detect missing members (in source but not in cache)
    for (const member of activeMembers) {
        const cached = cachedMembers.find(c => c.memberId === member.id);
        if (!cached) {
            discrepancies.push({
                type: 'missing',
                memberId: member.id,
                expected: 'in cache',
                actual: 'not found',
                action: 'republish enrollment event'
            });
        }
    }

    // Detect orphaned members (in cache but not in source)
    for (const cached of cachedMembers) {
        const member = activeMembers.find(m => m.id === cached.memberId);
        if (!member) {
            discrepancies.push({
                type: 'orphan',
                memberId: cached.memberId,
                expected: 'not in cache',
                actual: 'found in cache',
                action: 'remove from cache'
            });
        }
    }

    // Detect data mismatches
    for (const member of activeMembers) {
        const cached = cachedMembers.find(c => c.memberId === member.id);
        if (cached) {
            if (cached.enrollmentDate !== member.enrollmentDate) {
                discrepancies.push({
                    type: 'mismatch',
                    memberId: member.id,
                    field: 'enrollmentDate',
                    expected: member.enrollmentDate,
                    actual: cached.enrollmentDate,
                    action: 'update cache'
                });
            }
        }
    }

    console.log(`Found ${discrepancies.length} discrepancies`);

    // Remediate discrepancies
    let remediatedCount = 0;
    for (const discrepancy of discrepancies) {
        try {
            switch (discrepancy.type) {
                case 'missing':
                    // Republish enrollment event
                    await eventBus.publish('member.enrolled.reconciliation', {
                        memberId: discrepancy.memberId,
                        reason: 'reconciliation',
                        timestamp: new Date()
                    });
                    break;

                case 'orphan':
                    // Remove from cache
                    await claimsServiceClient.removeFromCache(discrepancy.memberId);
                    break;

                case 'mismatch':
                    // Update cache with correct value
                    const member = activeMembers.find(m => m.id === discrepancy.memberId);
                    await claimsServiceClient.updateCache(discrepancy.memberId, {
                        enrollmentDate: member.enrollmentDate
                    });
                    break;
            }
            remediatedCount++;
        } catch (error) {
            console.error(`Failed to remediate discrepancy: ${error}`, discrepancy);
        }
    }

    const duration = Date.now() - startTime;

    // Generate reconciliation report
    await reportingService.createReconciliationReport({
        timestamp: new Date(),
        duration: duration,
        totalMembers: activeMembers.length,
        discrepanciesFound: discrepancies.length,
        discrepanciesRemediated: remediatedCount,
        discrepancyRate: (discrepancies.length / activeMembers.length * 100).toFixed(4) + '%',
        details: discrepancies
    });

    // Alert if discrepancy rate high
    const discrepancyRate = discrepancies.length / activeMembers.length;
    if (discrepancyRate > 0.005) { // >0.5%
        await alertService.notify({
            severity: 'medium',
            message: `Reconciliation found high discrepancy rate: ${(discrepancyRate * 100).toFixed(2)}%`,
            details: { discrepancies: discrepancies.length, total: activeMembers.length }
        });
    }

    console.log(`Reconciliation completed: ${discrepancies.length} discrepancies, ${remediatedCount} remediated, Duration: ${duration}ms`);
});
```

**Step 5.2: Implement Real-Time Consistency Monitoring**

```javascript
// Real-time consistency lag monitoring
setInterval(async () => {
    // Check event bus consumer lag
    const lag = await serviceBusClient.getConsumerLag('claims-service-subscription');

    // Publish metric to Prometheus
    consistencyLagGauge.set({ service: 'claims-service' }, lag.lagSeconds);

    // Alert if lag exceeds threshold
    if (lag.messagesBacklog > 100000) {
        await alertService.notify({
            severity: 'high',
            message: 'Claims Service consumer lag exceeds threshold',
            details: {
                backlog: lag.messagesBacklog,
                lagSeconds: lag.lagSeconds,
                lastProcessedMessage: lag.lastProcessedTimestamp
            }
        });
    }
}, 60000); // Check every minute
```

**Step 5.3: Implement Data Quality Dashboards**

```yaml
