### Testing Strategy

Comprehensive testing ensures Data Consistency Pattern implementation is robust:

**1. Unit Tests** (Service-Level)

Test individual components in isolation.

```csharp
// Unit test: Transactional outbox
[Fact]
public async Task EnrollMember_ShouldWriteToOutbox_InSameTransaction() {
    // Arrange
    var memberService = new MemberService(_mockRepository.Object, _mockTransaction.Object);
    var request = new MemberEnrollmentRequest {
        FirstName = "Jane",
        LastName = "Doe",
        DateOfBirth = new DateTime(1985, 3, 15)
    };

    // Act
    await memberService.EnrollMemberAsync(request);

    // Assert
    _mockRepository.Verify(r => r.InsertAsync(It.IsAny<Member>()), Times.Once);
    _mockRepository.Verify(r => r.InsertOutboxEventAsync(It.IsAny<OutboxEvent>()), Times.Once);
    _mockTransaction.Verify(t => t.CommitAsync(), Times.Once);
}

// Unit test: Idempotency
[Fact]
public async Task ProcessMessage_WithDuplicateMessageId_ShouldSkipProcessing() {
    // Arrange
    var handler = new MemberEnrolledEventHandler(_mockMemberCache.Object, _mockProcessedMessages.Object);
    var message = CreateTestMessage("duplicate-msg-123");

    // Simulate message already processed
    _mockProcessedMessages.Setup(m => m.Exists("duplicate-msg-123")).ReturnsAsync(true);

    // Act
    await handler.HandleAsync(message);

    // Assert
    _mockMemberCache.Verify(c => c.Upsert(It.IsAny<object>(), It.IsAny<object>()), Times.Never);
}
```

**2. Integration Tests** (Cross-Service)

Test interactions between services.

```javascript
// Integration test: Saga success flow
describe('Member Enrollment Saga', () => {
    it('should complete all steps successfully', async () => {
        // Arrange
        const request = {
            firstName: 'Jane',
            lastName: 'Doe',
            dateOfBirth: '1985-03-15',
            ssn: '123-45-6789'
        };

        // Act
        const result = await memberEnrollmentSaga.execute(request);

        // Assert
        expect(result.status).toBe('Completed');
        expect(result.memberId).toBeDefined();

        // Verify all services updated
        const member = await memberService.getMember(result.memberId);
        expect(member).toBeDefined();

        const eligibility = await eligibilityService.getEligibility(result.memberId);
        expect(eligibility.status).toBe('active');

        const claimsEnabled = await claimsService.isClaimsEnabled(result.memberId);
        expect(claimsEnabled).toBe(true);

        const paymentAccount = await paymentService.getAccount(result.memberId);
        expect(paymentAccount).toBeDefined();
    });

    it('should compensate on failure', async () => {
        // Arrange
        const request = { /* ... */ };

        // Simulate Claims Service failure
        claimsService.enableClaimsProcessing = jest.fn().mockRejectedValue(new Error('Service unavailable'));

        // Act
        const result = await memberEnrollmentSaga.execute(request);

        // Assert
        expect(result.status).toBe('Failed');

        // Verify compensation executed
        const member = await memberService.findBySSN(request.ssn);
        expect(member.status).toBe('Enrollment Rolled Back');

        const eligibility = await eligibilityService.getEligibility(member.id);
        expect(eligibility).toBeNull(); // Should be deleted
    });
});
```

**3. Chaos Engineering Tests**

Simulate failures to validate resilience.

```javascript
// Chaos test: Network partition
describe('Network Partition Resilience', () => {
    it('should eventually converge after partition heals', async () => {
        // Arrange: Enroll member
        const member = await memberService.enrollMember({ /* ... */ });

        // Act: Simulate network partition (block Claims Service)
        await networkChaos.blockService('claims-service', { duration: 60000 }); // Block for 1 minute

        // Member Service publishes event (Claims Service can't receive due to partition)
        await memberService.updateAddress(member.id, { street: '456 Oak Ave' });

        // Wait for partition to heal
        await networkChaos.restoreService('claims-service');

        // Wait for eventual consistency
        await sleep(10000); // 10 seconds for message delivery

        // Assert: Claims Service should have updated address
        const cached = await claimsService.getMemberCache(member.id);
        expect(cached.address.street).toBe('456 Oak Ave');
    });
});

// Chaos test: Service crash
describe('Service Crash Recovery', () => {
    it('should resume saga after orchestrator crash', async () => {
        // Arrange
        const saga = await startMemberEnrollmentSaga({ /* ... */ });

        // Act: Crash orchestrator mid-saga (after step 2)
        await chaos.killService('saga-orchestrator');

        // Restart orchestrator
        await chaos.startService('saga-orchestrator');

        // Wait for saga recovery
        await sleep(5000);

        // Assert: Saga should complete or compensate
        const sagaStatus = await sagaRepository.getSagaStatus(saga.sagaId);
        expect(['Completed', 'Compensated']).toContain(sagaStatus);
    });
});
```

**4. Reconciliation Tests**

Validate inconsistency detection and remediation.

```javascript
// Reconciliation test
describe('Reconciliation Job', () => {
    it('should detect and remediate missing members', async () => {
        // Arrange: Create member in Member Service but not in Claims Service cache
        const member = await memberService.enrollMember({ /* ... */ });
        await claimsService.clearCache(member.id); // Simulate cache miss

        // Act: Run reconciliation
        const report = await reconciliationJob.run();

        // Assert
        expect(report.discrepancies).toContainEqual({
            type: 'missing',
            memberId: member.id
        });

        // Wait for remediation
        await sleep(5000);

        // Verify cache updated
        const cached = await claimsService.getMemberCache(member.id);
        expect(cached).toBeDefined();
        expect(cached.eligible).toBe(true);
    });
});
```

