### Example 3: Reconciliation - Detecting and Remediating Inconsistencies

**Business Context**:

Despite eventual consistency mechanisms (events, sagas), inconsistencies arise due to:

- Network partitions delaying event delivery
- Service outages causing missed events
- Bugs in event handlers
- Data corruption

Reconciliation processes detect and remediate inconsistencies to ensure system converges to consistent state.

**Scenario**: Member terminated in Member Service but Claims Service still shows eligible (missed termination event)

**Reconciliation Implementation**:

```javascript
// Nightly reconciliation job: Member eligibility consistency
const schedule = require('node-schedule');
const axios = require('axios');

// Run every night at 2 AM
schedule.scheduleJob('0 2 * * *', async () => {
    console.log('========================================');
    console.log('Starting Member Eligibility Reconciliation');
    console.log(`Timestamp: ${new Date().toISOString()}`);
    console.log('========================================');

    const startTime = Date.now();

    try {
        // Step 1: Query source of truth (Member Service)
        console.log('Step 1: Querying Member Service (source of truth)...');
        const memberServiceResponse = await axios.get('http://member-service/api/members/active', {
            params: { includeAll: true }
        });
        const activeMembers = memberServiceResponse.data;
        console.log(`Found ${activeMembers.length} active members in Member Service`);

        // Step 2: Query replica (Claims Service cache)
        console.log('Step 2: Querying Claims Service (replica)...');
        const claimsServiceResponse = await axios.get('http://claims-service/api/cache/members');
        const cachedMembers = claimsServiceResponse.data;
        console.log(`Found ${cachedMembers.length} members in Claims Service cache`);

        // Step 3: Compare and detect discrepancies
        console.log('Step 3: Comparing datasets...');
        const discrepancies = [];

        // Create lookup maps for efficient comparison
        const activeMemberMap = new Map(activeMembers.map(m => [m.id, m]));
        const cachedMemberMap = new Map(cachedMembers.map(m => [m.memberId, m]));

        // Check for missing members (in source but not in cache)
        for (const member of activeMembers) {
            const cached = cachedMemberMap.get(member.id);
            if (!cached) {
                discrepancies.push({
                    type: 'missing',
                    memberId: member.id,
                    firstName: member.firstName,
                    lastName: member.lastName,
                    expected: 'in cache as eligible',
                    actual: 'not found in cache',
                    action: 'republish member.enrolled event',
                    severity: 'medium',
                    impact: 'Claims for this member will be denied (member appears ineligible)'
                });
            } else {
                // Check for data mismatches
                if (cached.enrollmentDate !== member.enrollmentDate) {
                    discrepancies.push({
                        type: 'mismatch',
                        memberId: member.id,
                        field: 'enrollmentDate',
                        expected: member.enrollmentDate,
                        actual: cached.enrollmentDate,
                        action: 'update cache with correct enrollment date',
                        severity: 'low',
                        impact: 'Claims reporting may show incorrect enrollment date'
                    });
                }
            }
        }

        // Check for orphaned members (in cache but not in source)
        for (const cached of cachedMembers) {
            const member = activeMemberMap.get(cached.memberId);
            if (!member) {
                discrepancies.push({
                    type: 'orphan',
                    memberId: cached.memberId,
                    firstName: cached.firstName,
                    lastName: cached.lastName,
                    expected: 'not in cache (member terminated)',
                    actual: 'found in cache as eligible',
                    action: 'remove from cache',
                    severity: 'high',
                    impact: 'Claims for terminated member may be incorrectly approved (improper payment)'
                });
            }
        }

        console.log(`Detected ${discrepancies.length} discrepancies`);

        // Step 4: Analyze discrepancies
        const discrepancyRate = (discrepancies.length / activeMembers.length) * 100;
        console.log(`Discrepancy rate: ${discrepancyRate.toFixed(4)}%`);

        const discrepanciesBySeverity = {
            high: discrepancies.filter(d => d.severity === 'high').length,
            medium: discrepancies.filter(d => d.severity === 'medium').length,
            low: discrepancies.filter(d => d.severity === 'low').length
        };
        console.log(`Discrepancies by severity: High: ${discrepanciesBySeverity.high}, Medium: ${discrepanciesBySeverity.medium}, Low: ${discrepanciesBySeverity.low}`);

        // Step 5: Remediate discrepancies
        console.log('Step 4: Remediating discrepancies...');
        let remediatedCount = 0;
        const remediationErrors = [];

        for (const discrepancy of discrepancies) {
            try {
                switch (discrepancy.type) {
                    case 'missing':
                        // Republish member.enrolled event
                        const member = activeMembers.find(m => m.id === discrepancy.memberId);
                        await axios.post('http://member-service/api/events/republish', {
                            eventType: 'member.enrolled',
                            memberId: member.id,
                            reason: 'reconciliation',
                            data: {
                                memberId: member.id,
                                firstName: member.firstName,
                                lastName: member.lastName,
                                enrollmentDate: member.enrollmentDate
                            }
                        });
                        console.log(`  ✓ Republished member.enrolled for ${discrepancy.memberId}`);
                        remediatedCount++;
                        break;

                    case 'orphan':
                        // Remove from Claims Service cache
                        await axios.delete(`http://claims-service/api/cache/members/${discrepancy.memberId}`, {
                            params: { reason: 'reconciliation - member terminated' }
                        });
                        console.log(`  ✓ Removed orphaned member ${discrepancy.memberId} from cache`);
                        remediatedCount++;
                        break;

                    case 'mismatch':
                        // Update cache with correct value
                        const correctMember = activeMembers.find(m => m.id === discrepancy.memberId);
                        await axios.patch(`http://claims-service/api/cache/members/${discrepancy.memberId}`, {
                            [discrepancy.field]: discrepancy.expected,
                            reason: 'reconciliation'
                        });
                        console.log(`  ✓ Updated ${discrepancy.field} for ${discrepancy.memberId}`);
                        remediatedCount++;
                        break;
                }
            } catch (error) {
                console.error(`  ✗ Failed to remediate discrepancy for ${discrepancy.memberId}: ${error.message}`);
                remediationErrors.push({
                    discrepancy,
                    error: error.message
                });
            }
        }

        const duration = Date.now() - startTime;

        // Step 6: Generate reconciliation report
        const report = {
            timestamp: new Date().toISOString(),
            duration: `${duration}ms`,
            totalMembers: activeMembers.length,
            discrepanciesFound: discrepancies.length,
            discrepanciesRemediated: remediatedCount,
            discrepanciesFailed: remediationErrors.length,
            discrepancyRate: `${discrepancyRate.toFixed(4)}%`,
            discrepanciesBySeverity,
            discrepancies: discrepancies.slice(0, 100), // Sample of first 100 discrepancies
            remediationErrors
        };

        // Store report in database
        await db.reconciliationReports.insert(report);

        console.log('========================================');
        console.log('Reconciliation Complete');
        console.log(`Duration: ${duration}ms`);
        console.log(`Discrepancies: ${discrepancies.length} found, ${remediatedCount} remediated, ${remediationErrors.length} failed`);
        console.log('========================================');

        // Step 7: Alert if discrepancy rate high
        if (discrepancyRate > 0.5) { // >0.5% discrepancy rate
            await alertService.notify({
                severity: 'medium',
                title: 'High Member Eligibility Discrepancy Rate',
                message: `Reconciliation found ${discrepancyRate.toFixed(2)}% discrepancy rate (threshold: 0.5%)`,
                details: {
                    totalMembers: activeMembers.length,
                    discrepancies: discrepancies.length,
                    discrepancyRate: `${discrepancyRate.toFixed(4)}%`,
                    highSeverity: discrepanciesBySeverity.high,
                    reportUrl: `https://dashboard.gainwell.com/reconciliation/${report.id}`
                }
            });
        }

        // Alert if remediation failures
        if (remediationErrors.length > 0) {
            await alertService.notify({
                severity: 'high',
                title: 'Reconciliation Remediation Failures',
                message: `Failed to remediate ${remediationErrors.length} discrepancies`,
                details: {
                    failures: remediationErrors.map(e => ({
                        memberId: e.discrepancy.memberId,
                        error: e.error
                    }))
                }
            });
        }

    } catch (error) {
        console.error('Reconciliation job failed:', error);
        await alertService.notify({
            severity: 'critical',
            title: 'Reconciliation Job Failed',
            message: `Member eligibility reconciliation failed: ${error.message}`,
            details: { error: error.stack }
        });
    }
});

console.log('Reconciliation job scheduled (nightly at 2 AM)');
```

