### Example 4: Read-After-Write Consistency in Member Portal

**Business Context**:

Member updates address via web portal. User expectation: immediately see updated address when refreshing profile page. However, eventual consistency means Claims Service may not have updated address yet.

**Challenge**: Provide read-after-write consistency (user sees their own writes immediately) while maintaining eventual consistency across services.

**Solution**: Client-Side Caching + Session Stickiness

**Implementation**:

**Member Portal Backend** (Node.js):

```javascript
// Member Portal API: Update address endpoint
app.patch('/api/profile/address', async (req, res) => {
    const memberId = req.user.memberId; // From JWT token
    const { street, city, state, zip } = req.body;
    const sessionId = req.sessionID;

    try {
        // Update address in Member Service
        const response = await axios.patch(`http://member-service/api/members/${memberId}/address`, {
            street,
            city,
            state,
            zip
        });

        const updatedMember = response.data;

        // Cache updated member in session (for read-after-write consistency)
        req.session.memberCache = {
            memberId: updatedMember.id,
            version: updatedMember.version,
            address: updatedMember.address,
            cachedAt: new Date().toISOString(),
            ttl: 300000 // 5 minutes TTL
        };

        res.json({
            success: true,
            member: updatedMember,
            message: 'Address updated successfully'
        });

    } catch (error) {
        console.error('Address update failed:', error);
        res.status(500).json({ error: 'Failed to update address' });
    }
});

// Member Portal API: Get profile endpoint
app.get('/api/profile', async (req, res) => {
    const memberId = req.user.memberId;
    const sessionId = req.sessionID;

    try {
        // Check session cache first (read-after-write consistency)
        if (req.session.memberCache && req.session.memberCache.memberId === memberId) {
            const cacheAge = Date.now() - new Date(req.session.memberCache.cachedAt).getTime();

            if (cacheAge < req.session.memberCache.ttl) {
                console.log(`Serving from session cache: ${memberId}, Cache age: ${cacheAge}ms`);

                // Serve from cache
                res.json({
                    member: req.session.memberCache,
                    source: 'session-cache',
                    cacheAge: `${cacheAge}ms`
                });
                return;
            } else {
                console.log(`Session cache expired: ${memberId}`);
                delete req.session.memberCache; // Evict expired cache
            }
        }

        // Cache miss or expired: query Member Service
        console.log(`Querying Member Service: ${memberId}`);
        const response = await axios.get(`http://member-service/api/members/${memberId}`);
        const member = response.data;

        res.json({
            member,
            source: 'member-service',
            cacheAge: 'N/A'
        });

    } catch (error) {
        console.error('Profile retrieval failed:', error);
        res.status(500).json({ error: 'Failed to retrieve profile' });
    }
});
```

**Member Portal Frontend** (React):

```jsx
// Member Portal: Address update with optimistic UI
import React, { useState } from 'react';
import axios from 'axios';

function AddressForm({ member, onUpdate }) {
    const [address, setAddress] = useState(member.address);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [optimisticUpdate, setOptimisticUpdate] = useState(null);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        // Optimistic UI: show updated address immediately
        setOptimisticUpdate(address);

        try {
            const response = await axios.patch('/api/profile/address', address);

            // Update successful: clear optimistic update
            setOptimisticUpdate(null);
            onUpdate(response.data.member);

            // Show success message
            alert('Address updated successfully!');

        } catch (error) {
            console.error('Address update failed:', error);

            // Revert optimistic update
            setOptimisticUpdate(null);
            setAddress(member.address); // Revert to original

            alert('Failed to update address. Please try again.');
        } finally {
            setIsSubmitting(false);
        }
    };

    const displayAddress = optimisticUpdate || address;

    return (
        <div>
            <h2>Update Address</h2>
            <form onSubmit={handleSubmit}>
                <input
                    type="text"
                    placeholder="Street"
                    value={displayAddress.street}
                    onChange={(e) => setAddress({ ...address, street: e.target.value })}
                    disabled={isSubmitting}
                />
                <input
                    type="text"
                    placeholder="City"
                    value={displayAddress.city}
                    onChange={(e) => setAddress({ ...address, city: e.target.value })}
                    disabled={isSubmitting}
                />
                <input
                    type="text"
                    placeholder="State"
                    value={displayAddress.state}
                    onChange={(e) => setAddress({ ...address, state: e.target.value })}
                    disabled={isSubmitting}
                />
                <input
                    type="text"
                    placeholder="ZIP"
                    value={displayAddress.zip}
                    onChange={(e) => setAddress({ ...address, zip: e.target.value })}
                    disabled={isSubmitting}
                />
                <button type="submit" disabled={isSubmitting}>
                    {isSubmitting ? 'Updating...' : 'Update Address'}
                </button>
            </form>

            {optimisticUpdate && (
                <p style={{ color: 'orange' }}>
                    ⏳ Updating address... (This may take a few seconds)
                </p>
            )}
        </div>
    );
}
```

**User Experience Timeline**:

```text
T+0ms:    User clicks "Update Address" button
T+10ms:   Optimistic UI: Address immediately updated on screen (client-side)
T+10ms:   Loading indicator: "⏳ Updating address..."
T+150ms:  HTTP request reaches Member Portal backend
T+200ms:  Member Portal updates Member Service
T+250ms:  Member Service persists address, returns response
T+300ms:  Member Portal caches updated address in session
T+350ms:  HTTP response reaches browser
T+360ms:  Optimistic UI confirmed; loading indicator removed
T+360ms:  User sees: "✓ Address updated successfully!"
T+361ms:  User clicks "Refresh" button
T+362ms:  Member Portal serves from session cache (read-after-write consistency)
T+362ms:  User sees updated address (consistent with their write)

User Experience: Instant feedback (optimistic UI) + guaranteed read-after-write consistency
```

**Benefits Demonstrated**:

1. **Instant User Feedback**: Optimistic UI provides immediate feedback; user doesn't wait for backend
2. **Read-After-Write Consistency**: User always sees their own writes (session cache guarantees consistency)
3. **Eventual Consistency Preserved**: Other users/services see updated address after event propagation
4. **Graceful Degradation**: If update fails, optimistic UI reverts; user notified of failure

